  const fr=Math.floor(t/18)%4,kk=Math.max(1,Math.round(s/2)),big=kk>=2,im=(big?n.F:n.f)[fr]||n.f[0],k=big?kk/2:kk,w=im.width*k,h=im.height*k,bob=Math.round(Math.sin(t/25)*kk);   /* same sizes as the classic ngen: 96 px, or 192 px from size 2.5 up */
